DROP TABLE IF EXISTS `project_info_node`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `project_info_node` (
  `id` varchar(64) NOT NULL COMMENT '节点UUID(客户端生成)',
  `project_id` varchar(64) NOT NULL COMMENT '所属项目ID',
  `parent_id` varchar(64) DEFAULT NULL COMMENT '父节点ID, NULL=根节点',
  `title` varchar(255) NOT NULL COMMENT '节点标题',
  `content_type` varchar(32) NOT NULL COMMENT '内容类型: text/image/file/...',
  `value` text COMMENT '节点值',
  `sort_order` int NOT NULL COMMENT '同级排序',
  `created_at` varchar(30) NOT NULL COMMENT '创建时间',
  `updated_at` varchar(30) NOT NULL COMMENT '更新时间',
  `template_node_id` varchar(64) DEFAULT NULL COMMENT '来源的详情模板节点ID（模板同步锚点）；用户自建节点为 NULL',
  PRIMARY KEY (`id`),
  KEY `idx_pn_project` (`project_id`),
  KEY `idx_pn_project_parent_sort` (`project_id`,`parent_id`,`sort_order`),
  KEY `idx_pn_parent` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
