--
-- Table structure for table `project_info_node_change`
--

DROP TABLE IF EXISTS `project_info_node_change`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `project_info_node_change` (
  `id` varchar(64) NOT NULL COMMENT '记录UUID',
  `project_id` varchar(64) NOT NULL COMMENT '所属项目ID',
  `node_id` varchar(64) DEFAULT NULL COMMENT '被操作的节点ID；整树级操作为 NULL',
  `parent_id` varchar(64) DEFAULT NULL COMMENT '上级节点ID（删除记录据此在父节点历史里展示）',
  `node_title` varchar(255) NOT NULL COMMENT '操作时的节点标题快照',
  `action` varchar(16) NOT NULL COMMENT '操作类型: create/update/move/delete/import/sync',
  `operator` varchar(64) DEFAULT NULL COMMENT '操作人登录名（无法识别时为 NULL）',
  `operator_name` varchar(64) DEFAULT NULL COMMENT '操作人显示名',
  `detail` text COMMENT '具体变动的人话描述',
  `created_at` varchar(30) NOT NULL COMMENT '操作时间',
  PRIMARY KEY (`id`),
  KEY `idx_pnc_parent` (`project_id`,`parent_id`),
  KEY `idx_pnc_node` (`project_id`,`node_id`),
  KEY `idx_pnc_project_time` (`project_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

